def hcf(a, b):
    """Retorna o maior divisor comum usando recursão (algoritmo de Euclides)."""
    if b == 0:
        return a
    return hcf(b, a % b)

def ler_int(prompt):
    while True:
        try:
            return int(input(prompt))
        except ValueError:
            print('Valor inválido, tente novamente.')

if __name__ == '__main__':
    x = ler_int('Primeiro número: ')
    y = ler_int('Segundo número: ')
    print('MDC:', hcf(x, y))
